#[using="Type"] Lemma in_ivs_map_den : forall E ms m z,
  In m ms ->
  bv_unsigned (edenot E (am_base m)) <= z < bv_unsigned (edenot E (am_base m)) + bv_unsigned (edenot E (am_len m)) ->
  in_ivs z (map (amap_den E) ms) = true.
Proof.
